CREATE TYPE "PositionStatus" AS ENUM ('draft','rubric_review','screening','closed');
CREATE TYPE "CriterionClassification" AS ENUM ('must_have','preferred','logistics','informational');
CREATE TYPE "RubricStatus" AS ENUM ('draft','approved','superseded');
CREATE TABLE "positions" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"status" "PositionStatus" NOT NULL DEFAULT 'draft',"employment_type" TEXT NOT NULL,"location" TEXT,"workplace_preference" TEXT,"compensation_min" INTEGER,"compensation_max" INTEGER,"minimum_experience" INTEGER,"preferred_experience" INTEGER,"notice_period_days" INTEGER,"shift_travel" TEXT,"work_authorization" TEXT,"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "positions_organization_id_created_at_idx" ON "positions"("organization_id","created_at");
CREATE TABLE "provider_executions" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"provider" TEXT NOT NULL,"operation" TEXT NOT NULL,"model" TEXT NOT NULL,"prompt_version" TEXT NOT NULL,"schema_version" TEXT NOT NULL,"provider_request_id" TEXT,"latency_ms" INTEGER,"status" TEXT NOT NULL,"normalized_error" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "provider_executions_organization_id_created_at_idx" ON "provider_executions"("organization_id","created_at");
CREATE TABLE "job_descriptions" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"position_id" TEXT NOT NULL REFERENCES "positions"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"source_type" TEXT NOT NULL,"raw_text" TEXT,"structured_data" JSONB NOT NULL DEFAULT '{}',"extraction_mode" TEXT NOT NULL,"provider_execution_id" TEXT,"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "job_descriptions_organization_id_position_id_version_key" UNIQUE("organization_id","position_id","version"));
CREATE TABLE "evaluation_rubrics" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"position_id" TEXT NOT NULL REFERENCES "positions"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"status" "RubricStatus" NOT NULL DEFAULT 'draft',"approved_by_id" TEXT,"approved_at" TIMESTAMP(3),"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "evaluation_rubrics_organization_id_position_id_version_key" UNIQUE("organization_id","position_id","version"));
CREATE TABLE "rubric_criteria" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"rubric_id" TEXT NOT NULL REFERENCES "evaluation_rubrics"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"criterion_type" TEXT NOT NULL,"classification" "CriterionClassification" NOT NULL,"weight" INTEGER NOT NULL,"evidence_expectations" TEXT NOT NULL,"display_order" INTEGER NOT NULL);
CREATE INDEX "rubric_criteria_organization_id_rubric_id_display_order_idx" ON "rubric_criteria"("organization_id","rubric_id","display_order");
CREATE TABLE "hiring_panel_members" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"position_id" TEXT NOT NULL REFERENCES "positions"("id") ON DELETE CASCADE,"organization_member_id" TEXT NOT NULL,"panel_role" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "hiring_panel_members_organization_id_position_id_organization_member_id_key" UNIQUE("organization_id","position_id","organization_member_id"));
